import React from "react"

/**
 * A five-year annual bar chart, built from flexbox and one absolutely
 * positioned zero line. Three of these do not justify a charting library.
 *
 * The zero baseline is the point: five of the fourteen companies lose money
 * every year, so bars must be able to hang BELOW the axis rather than being
 * clipped to zero or drawn as tiny positive stubs. The plot is split into an
 * upper and a lower band whose heights are proportional to the positive and
 * negative extents of the data, so a series that is entirely positive uses the
 * full height and one that straddles zero puts the axis where it belongs.
 *
 * Bars use three tints of the accent so the most recent year reads as the
 * subject and earlier years as context — never a gradient. Negative bars are
 * --down, because that is what the colour means everywhere else in the product.
 */

const TINTS = ["--accent-tint-1", "--accent-tint-2", "--accent-tint-3"]

/** Later years get a stronger tint; the final year is the strongest. */
function tintFor(index, count) {
  if (index === count - 1) return TINTS[2]
  if (index >= count - 3) return TINTS[1]
  return TINTS[0]
}

export default function BarChart({ title, data, format, height = 132 }) {
  const points = Array.isArray(data) ? data.filter(d => d && Number.isFinite(d.value)) : []
  if (points.length === 0) {
    return (
      <section className="barchart">
        <h3 className="barchart__title">{title}</h3>
        <p className="barchart__empty">No annual data.</p>
      </section>
    )
  }

  let max = 0
  let min = 0
  for (const p of points) {
    if (p.value > max) max = p.value
    if (p.value < min) min = p.value
  }

  const span = max - min || Math.abs(max) || 1
  // Share of the plot given to the area above zero.
  const positiveShare = max <= 0 ? 0 : max / span
  const upper = height * positiveShare
  const lower = height - upper

  return (
    <section className="barchart">
      <h3 className="barchart__title">{title}</h3>

      <div className="barchart__plot" style={{ height: height + "px" }}>
        {/* The zero line only earns its keep when something is negative. */}
        {min < 0 && (
          <span
            className="barchart__zero"
            style={{ top: upper + "px" }}
            aria-hidden="true"
          />
        )}

        {points.map((point, index) => {
          const positive = point.value >= 0
          const band = positive ? upper : lower
          const magnitude = positive
            ? max === 0 ? 0 : (point.value / max) * band
            : min === 0 ? 0 : (Math.abs(point.value) / Math.abs(min)) * band

          return (
            <div className="barchart__col" key={point.year}>
              <div className="barchart__upper" style={{ height: upper + "px" }}>
                {positive && (
                  <>
                    <span className="barchart__value">{format(point.value)}</span>
                    <span
                      className="barchart__bar"
                      style={{
                        height: Math.max(2, magnitude) + "px",
                        background: `var(${tintFor(index, points.length)})`,
                      }}
                    />
                  </>
                )}
              </div>

              <div className="barchart__lower" style={{ height: lower + "px" }}>
                {!positive && (
                  <>
                    <span
                      className="barchart__bar barchart__bar--neg"
                      style={{ height: Math.max(2, magnitude) + "px" }}
                    />
                    <span className="barchart__value barchart__value--neg">
                      {format(point.value)}
                    </span>
                  </>
                )}
              </div>

              <span className="barchart__year">{point.year}</span>
            </div>
          )
        })}
      </div>
    </section>
  )
}
