import React from "react"
import { Link } from "gatsby"

/**
 * Breadcrumb — trail of ancestor pages.
 *
 * Props:
 *   items  [{ label, to }] — the final item omits "to" and becomes the current page.
 */

function Breadcrumb({ items }) {
  const list = Array.isArray(items) ? items.filter(Boolean) : []
  if (list.length === 0) return null

  const lastIndex = list.length - 1

  return (
    <nav className="breadcrumb" aria-label="Breadcrumb">
      <ol className="breadcrumb__list">
        {list.map((item, index) => (
          <li className="breadcrumb__item" key={item.to || item.label || index}>
            {item.to ? (
              <Link className="breadcrumb__link" to={item.to}>
                {item.label}
              </Link>
            ) : (
              <span className="breadcrumb__current" aria-current="page">
                {item.label}
              </span>
            )}
            {index < lastIndex ? (
              <span className="breadcrumb__sep" aria-hidden="true">
                /
              </span>
            ) : null}
          </li>
        ))}
      </ol>
    </nav>
  )
}

export default Breadcrumb
