import React from "react"

/**
 * A signed, coloured, monospaced number.
 *
 * Renders a true minus sign (U+2212) rather than a hyphen so negative figures
 * line up with positives in a tabular column. Non-finite input renders an em
 * dash in the flat tone instead of NaN.
 */
export default function Delta({
  value,
  percent = false,
  digits = 2,
  showGlyph = true,
  prefix = "",
  size,
  className,
}) {
  const finite = value !== null && Number.isFinite(value)
  const tone = !finite || value === 0 ? "flat" : value > 0 ? "up" : "down"
  const classes = [
    "delta",
    "delta--" + tone,
    size === "lg" ? "delta--lg" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ")

  if (!finite) {
    return (
      <span className={classes}>
        <span className="delta__value">—</span>
      </span>
    )
  }

  const sign = value > 0 ? "+" : value < 0 ? "\u2212" : ""
  const body = prefix + Math.abs(value).toFixed(digits) + (percent ? "%" : "")

  return (
    <span className={classes}>
      {showGlyph && tone !== "flat" && (
        <span className="delta__glyph" aria-hidden="true">
          {tone === "up" ? "▲" : "▼"}
        </span>
      )}
      <span className="delta__value">
        {sign}
        {body}
      </span>
    </span>
  )
}
