/**
 * Data-access / plan configuration.  (SMT-007)
 *
 * ---------------------------------------------------------------------------
 * ONE PLACE DECIDES WHAT IS AVAILABLE
 * ---------------------------------------------------------------------------
 * Every lock in the UI reads from this file. Upgrading the Massive plan is
 * therefore a one-line change here — flip a capability to `true` — and every
 * tab, filter and panel unlocks without touching a component. That is the
 * point of the indirection: nobody should have to hunt through JSX to find out
 * why something is greyed out, or edit five files to turn it back on.
 *
 * ---------------------------------------------------------------------------
 * THE THREE STATES THIS FILE EXISTS TO KEEP APART
 * ---------------------------------------------------------------------------
 *   ENTITLED + has data      → render it
 *   ENTITLED + no data       → "no data" — a real, factual answer
 *   NOT ENTITLED             → "requires an upgrade" — says nothing about
 *                              whether the data exists
 *
 * Collapsing the third into the second is the failure this prevents. A locked
 * metric must never render as 0, false, "N/A", an empty table, or "0 companies
 * match" — all of which read as findings about the market rather than about
 * our subscription.
 *
 * Pure data. Safe in the browser: no key, no endpoint call, no secret.
 */

/**
 * What the key was actually observed to do, probed 2026-09-21 against
 * api.massive.com. Recorded because "the plan does not include X" and "the
 * endpoint returns 403" are different claims, and only the second is evidence.
 *
 * Findings:
 *   /vX/reference/financials   HTTP 200, full statements returned
 *   /vX/reference/ratios       HTTP 404, no such endpoint on this key
 *   /v3/reference/dividends    HTTP 200
 *   /v3/reference/splits       HTTP 200
 *   /v3/reference/options/*    HTTP 403, explicitly not entitled
 */
export const PROBE = {
  probedAt: "2026-09-21",
  results: {
    financials: { status: 200, note: "Returned six annual filings for AAPL with full statements." },
    ratios: { status: 404, note: "No ratios endpoint on this key." },
    dividends: { status: 200, note: "Returned dividend records." },
    splits: { status: 200, note: "Returned split records." },
    options: { status: 403, note: "Explicitly not entitled." },
  },
}

export const PLAN_NAME = "Massive · Stocks Basic (free)"

/**
 * Capability switches. `true` means the UI may render it.
 *
 * NOTE ON `financialsAndRatios`: it is set to false because the brief says the
 * Financials & Ratios dataset is not part of this subscription. The probe
 * above found /vX/reference/financials answering 200 with real statements, so
 * the statement tabs would very likely work today — flipping this single flag
 * is all it takes to find out. `ratios` is separately and genuinely absent
 * (404), so the Ratios tab stays locked either way.
 */
export const CAPABILITIES = {
  /** Daily and minute aggregates. */
  marketData: true,
  /** Ticker reference: name, exchange, share count, market cap, employees. */
  reference: true,
  /** SEC/EDGAR filing metadata. Explicitly available on the free tier. */
  secFilings: true,
  /** Corporate actions. */
  splits: true,
  dividends: true,
  /** Income statement, balance sheet and cash flow. */
  financialsAndRatios: false,
  /** Pre-computed ratio dataset. Absent from this key regardless of the above. */
  ratios: false,
  /** Options chains and contracts. */
  options: false,
  /** Forward estimates: forward P/E, analyst targets. */
  estimates: false,
}

/** The message every lock shows. One wording, one place. */
export const LOCK_MESSAGE =
  "Requires Massive Financials & Ratios. This data will become available when the Massive plan is upgraded."

/** The short line the toast shows on click. */
export const LOCK_TOAST = "Requires a paid Massive subscription to unlock"

export function isEntitled(capability) {
  return CAPABILITIES[capability] === true
}

/**
 * Why a capability is locked, or null when it is not.
 *
 * Returning null for an entitled capability lets callers write
 * `const lock = lockFor(x)` and treat it as a plain truthiness check.
 */
export function lockFor(capability) {
  if (isEntitled(capability)) return null
  return {
    capability,
    plan: PLAN_NAME,
    message: LOCK_MESSAGE,
    toast: LOCK_TOAST,
  }
}

/* --------------------------------------------------------------------------
   What each screen element depends on
   --------------------------------------------------------------------------
   Kept here rather than beside each component so the whole entitlement surface
   can be read, and audited, in one place.
   -------------------------------------------------------------------------- */

/** Fundamentals tabs → the capability each one needs. */
export const TAB_CAPABILITY = {
  Overview: "reference",
  Financials: "financialsAndRatios",
  "Income statement": "financialsAndRatios",
  "Balance sheet": "financialsAndRatios",
  "Cash flow": "financialsAndRatios",
  Ratios: "ratios",
  /*
   * Earnings is EPS history by fiscal year, which comes from the income
   * statement in the financials feed — not from a separate earnings endpoint.
   * It is therefore gated with the statements rather than locked on its own
   * account, and unlocks with them.
   */
  Earnings: "financialsAndRatios",
  /* Free tier. Built from filing metadata, and must work now. */
  "SEC filings": "secFilings",
}

/** Fundamental filters → the capability each one needs. */
export const FILTER_CAPABILITY = {
  /* Market cap is price x share count, both from reference + aggregates. */
  marketCap: "reference",
  /* Exchange comes from the ticker reference record. */
  exchange: "reference",
  /* Average volume comes from daily aggregates. */
  minLiquidity: "marketData",
  /* Filing metadata only — counts filings, reads no statement line. */
  hasFilings: "secFilings",
  /* Exchange membership only. */
  excludeOtc: "reference",

  /* These read income-statement lines and are gated with them. */
  revenueGrowth: "financialsAndRatios",
  profitability: "financialsAndRatios",
  positiveRevenue: "financialsAndRatios",
  credibleOnly: "financialsAndRatios",
}

/** True when this filter may take part in filtering right now. */
export function filterEnabled(key) {
  const capability = FILTER_CAPABILITY[key]
  // An unmapped filter is treated as free rather than silently locked.
  return capability === undefined ? true : isEntitled(capability)
}

/**
 * Strips locked keys out of a filter set before it is applied.
 *
 * A locked filter must not narrow the result — otherwise the screen reports
 * "0 companies match", which reads as a fact about the market when it is a
 * fact about the subscription.
 */
export function applicableFilters(filters) {
  const out = {}
  for (const [key, value] of Object.entries(filters || {})) {
    if (filterEnabled(key)) out[key] = value
  }
  return out
}
