import React from "react"

/**
 * Checkbox — a styled box driven by a real checkbox input.
 *
 * The CSS depends on .checkbox__input being the immediate previous sibling of
 * .checkbox__box, so the DOM order here must not change.
 *
 * Props: { checked, onChange, label, id, disabled, ariaLabel }
 */

function noop() {}

function Checkbox({ checked = false, onChange, label, id, disabled = false, ariaLabel }) {
  const handleChange = typeof onChange === "function" ? onChange : noop
  const fallbackLabel = label ? undefined : ariaLabel || "Checkbox"

  return (
    <label className="checkbox" htmlFor={id}>
      <input
        className="checkbox__input"
        type="checkbox"
        id={id}
        checked={!!checked}
        disabled={!!disabled}
        onChange={handleChange}
        aria-label={fallbackLabel}
      />
      <span className="checkbox__box">
        <span className="checkbox__mark" aria-hidden="true">
          <svg viewBox="0 0 12 12" width="12" height="12" focusable="false" aria-hidden="true">
            <path
              d="M2.5 6.2 L4.8 8.5 L9.5 3.8"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </span>
      </span>
      {label ? <span className="checkbox__label">{label}</span> : null}
    </label>
  )
}

export default Checkbox
