import React, { useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import TickerMark from "../components/ui/TickerMark"
import Delta from "../components/ui/Delta"
import Icon from "../components/ui/Icon"
import Select from "../components/ui/Select"
import BarChart from "../components/fundamentals/BarChart"
import FilterRail, {
  DEFAULT_FILTERS,
  filterCompanies,
} from "../components/fundamentals/FilterRail"

import { COMPANIES, getCompany, ANCHOR_DATE } from "../data/companies"
import { getSessionChange } from "../data/markets"
import { getSecFilings } from "../data/fundamentals"
import { lockFor, TAB_CAPABILITY, LOCK_TOAST } from "../data/plan"
import LockBadge from "../components/ui/LockBadge"
import Toast, { useToast } from "../components/ui/Toast"

/* -------------------------------------------------------------------------- */
/* Formatting                                                                  */
/* -------------------------------------------------------------------------- */

const DASH = "—"
const isNum = v => v !== null && v !== undefined && Number.isFinite(v)

function money(value, digits = 2) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  const sign = value < 0 ? "−" : ""
  if (abs >= 1e12) return sign + "$" + (abs / 1e12).toFixed(digits) + "T"
  if (abs >= 1e9) return sign + "$" + (abs / 1e9).toFixed(digits) + "B"
  if (abs >= 1e6) return sign + "$" + (abs / 1e6).toFixed(1) + "M"
  if (abs >= 1e3) return sign + "$" + (abs / 1e3).toFixed(1) + "K"
  return sign + "$" + abs.toFixed(2)
}

function count(value) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  if (abs >= 1e9) return (value / 1e9).toFixed(2) + "B"
  if (abs >= 1e6) return (value / 1e6).toFixed(1) + "M"
  if (abs >= 1e3) return (value / 1e3).toFixed(1) + "K"
  return value.toLocaleString("en-US")
}

const pct = (value, digits = 1) =>
  isNum(value) ? (value * 100).toFixed(digits) + "%" : DASH

/**
 * Sign goes OUTSIDE the currency symbol, and uses a true minus (U+2212) so
 * negatives align with positives in a tabular column. "$-1.79" is wrong on both
 * counts and looks like a typo next to money()'s "−$348.0M".
 */
const usd = (value, digits = 2) => {
  if (!isNum(value)) return DASH
  return (value < 0 ? "−$" : "$") + Math.abs(value).toFixed(digits)
}
const num = (value, digits = 1) => (isNum(value) ? value.toFixed(digits) : DASH)

const TAB_LABELS = [
  "Overview",
  "Financials",
  "Income statement",
  "Balance sheet",
  "Cash flow",
  "Ratios",
  "Earnings",
  "SEC filings",
]

/** Each tab paired with the lock its capability implies, or null. */
const TABS = TAB_LABELS.map(name => ({ name, lock: lockFor(TAB_CAPABILITY[name]) }))

/* -------------------------------------------------------------------------- */
/* Small presentational pieces                                                 */
/* -------------------------------------------------------------------------- */

function Row({ label, value, chip, hint }) {
  return (
    <div className="kvlist__row">
      <span className="kvlist__label" title={hint}>
        {label}
      </span>
      <span className="kvlist__right">
        {chip}
        <span className="kvlist__value">{value}</span>
      </span>
    </div>
  )
}

/** A growth figure rendered as a coloured chip beside its absolute value. */
function GrowthChip({ value }) {
  if (!isNum(value)) return null
  return <Delta className="delta--sm" value={value * 100} percent digits={1} />
}

function RangeTrack({ low, high, price }) {
  const span = isNum(low) && isNum(high) ? high - low : 0
  const position = span > 0 ? ((price - low) / span) * 100 : null
  const clamped = position === null ? null : Math.round(Math.max(0, Math.min(100, position)) * 100) / 100

  return (
    <div className="range">
      <div className="range__track">
        {clamped !== null && (
          <span className="range__marker" style={{ left: clamped + "%" }} />
        )}
      </div>
      <div className="range__ends">
        <span className="range__end">{usd(low)}</span>
        <span className="range__end">{usd(high)}</span>
      </div>
    </div>
  )
}

/**
 * What a locked tab shows instead of its data.
 *
 * Deliberately NOT an empty table, a zero, or an "N/A". Each of those reads as
 * a finding about the company; this has to read as a fact about our
 * subscription. The distinction is the whole point of the lock.
 */
function LockedPanel({ tab, lock }) {
  return (
    <div className="locked" role="tabpanel" aria-label={`${tab} — locked`}>
      <div className="locked__icon" aria-hidden="true">
        <svg viewBox="0 0 24 24" width="22" height="22">
          <path
            d="M17 9V7a5 5 0 0 0-10 0v2H6a1 1 0 0 0-1 1v9a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-9a1 1 0 0 0-1-1h-1ZM9 7a3 3 0 0 1 6 0v2H9V7Z"
            fill="currentColor"
          />
        </svg>
      </div>
      <h3 className="locked__title">{tab} is not included in the current plan</h3>
      <p className="locked__text">{lock.message}</p>
      <p className="locked__plan">
        Current plan: <strong>{lock.plan}</strong>
      </p>
      <p className="locked__note">
        This is a subscription limit, not an absence of data — nothing here is being
        reported as zero or empty.
      </p>
    </div>
  )
}

/**
 * SEC filings. Free tier, so this must work rather than be locked.
 *
 * Every row carries its real accession number and links to the document on
 * EDGAR, which is what lets a client verify a figure against the source rather
 * than take the screen's word for it.
 */
function FilingsPanel({ filings, company }) {
  if (!filings.length) {
    return (
      <div className="tabs__empty" role="tabpanel">
        <p className="tabs__empty-text">
          No filings have been ingested for {company.symbol}. This is a genuine absence of
          data, not a plan limit.
        </p>
      </div>
    )
  }

  return (
    <div className="filings" role="tabpanel">
      <Panel
        title="SEC filings"
        subtitle={`${filings.length} annual filings from EDGAR, newest first. Every row links to the source document.`}
        flush
      >
        <table className="filings__table">
          <thead>
            <tr>
              <th>Form</th>
              <th>Fiscal year</th>
              <th>Period</th>
              <th>Filed</th>
              <th>Accession number</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {filings.map(f => (
              <tr key={f.accession || `${f.fiscalYear}-${f.filingDate}`}>
                <td>
                  <span className="filings__form">{f.formType}</span>
                </td>
                <td className="num">{f.fiscalYear ?? DASH}</td>
                <td className="filings__period">
                  {f.periodStart} → {f.periodEnd}
                </td>
                <td className="num">{f.filingDate ?? DASH}</td>
                <td className="filings__accession">{f.accession ?? DASH}</td>
                <td>
                  {f.edgarUrl ? (
                    <a
                      className="filings__link"
                      href={f.edgarUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      View on EDGAR
                    </a>
                  ) : (
                    <span className="muted">{DASH}</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>
      <p className="filings__note">
        Filing metadata comes from Massive's SEC feed, which is included in the current
        plan. CIK {filings[0].cik} · {filings[0].companyName}
      </p>
    </div>
  )
}

/* -------------------------------------------------------------------------- */

export default function FundamentalsPage({ location }) {
  const [filters, setFilters] = useState(DEFAULT_FILTERS)
  const [applied, setApplied] = useState(DEFAULT_FILTERS)
  const [symbol, setSymbol] = useState("AAPL")
  const [tab, setTab] = useState("Overview")
  const { toast, show: showToast, dismiss: dismissToast } = useToast()
  const activeLock = TABS.find(t => t.name === tab)?.lock ?? null
  const filings = useMemo(() => getSecFilings(symbol), [symbol])

  // The applied set drives the dropdown; the draft set drives the controls, so
  // "Apply filters" is a real action rather than decoration.
  const universe = useMemo(() => filterCompanies(applied), [applied])
  const draftMatches = useMemo(() => filterCompanies(filters), [filters])

  // If the applied filters exclude the selected company, fall back to the first
  // surviving one rather than rendering a page about something filtered out.
  const activeSymbol = useMemo(() => {
    if (universe.some(c => c.symbol === symbol)) return symbol
    return universe.length ? universe[0].symbol : symbol
  }, [universe, symbol])

  const company = getCompany(activeSymbol)
  const change = useMemo(() => getSessionChange(activeSymbol), [activeSymbol])

  const years = company.financials
  const revenueSeries = years.map(y => ({ year: y.year, value: y.revenue }))
  const incomeSeries = years.map(y => ({ year: y.year, value: y.netIncome }))
  const epsSeries = years.map(y => ({ year: y.year, value: y.eps }))

  const options = universe.map(c => ({ label: `${c.symbol} — ${c.name}`, value: c.symbol }))

  return (
    <Shell location={location}>
      <div className="page">
        <div className="page__breadcrumb">
          <Breadcrumb items={[{ label: "Home", to: "/" }, { label: "Fundamentals" }]} />
        </div>

        <header className="page__head">
          <div className="page__heading">
            <h1 className="page__title">Fundamentals</h1>
            <p className="page__lede">
              Valuation, growth, margins and the balance sheet, side by side.
            </p>
          </div>
        </header>

        <div className="fund">
          {/* ---------------- Filter rail ---------------- */}
          <div className="fund__rail">
            {/* The picker sits above the filters because the filters shrink it:
                applying a screen removes companies from this list, which is the
                only honest way to show a filter panel is doing something. */}
            <div className="fund__picker">
              <Select
                label="Company"
                options={options}
                value={activeSymbol}
                onChange={setSymbol}
              />
              <p className="fund__picker-note">
                {options.length} of {COMPANIES.length} companies pass the applied filters
              </p>
            </div>

            <FilterRail
              filters={filters}
              onChange={setFilters}
              onApply={() => setApplied(filters)}
              onReset={() => {
                setFilters(DEFAULT_FILTERS)
                setApplied(DEFAULT_FILTERS)
              }}
              matchCount={draftMatches.length}
              total={COMPANIES.length}
              onLocked={() => showToast(LOCK_TOAST)}
            />
          </div>

          {/* ---------------- Main ---------------- */}
          <div className="fund__main">
            {/* Company header */}
            <section className="co-head">
              <div className="co-head__left">
                <TickerMark symbol={company.symbol} size={56} />
                <div className="co-head__identity">
                  <h2 className="co-head__symbol">{company.symbol}</h2>
                  <p className="co-head__name">{company.name}</p>
                  <p className="co-head__meta">
                    {company.sector} · {company.industry}
                  </p>
                  <div className="co-head__chips">
                    <span className="co-head__chip">{company.exchange}</span>
                    <span
                      className="co-head__chip"
                      title="Approximated from market cap; real index membership has committee rules this prototype does not model."
                    >
                      {company.indexMembership}
                    </span>
                    <span className="co-head__chip">{company.capSize}</span>
                  </div>
                </div>
              </div>

              <div className="co-head__right">
                <span className="co-head__price">{usd(company.price)}</span>
                <span className="co-head__change">
                  <Delta value={change.changeAbs} digits={2} showGlyph={false} />
                  <Delta value={change.changePct} percent digits={2} />
                </span>
                <span className="co-head__asof">As of {ANCHOR_DATE} · 16:00 ET</span>
                <button type="button" className="btn btn--secondary co-head__watch">
                  <Icon name="star" size={15} className="btn__icon" />
                  Add to watchlist
                </button>
              </div>
            </section>

            {/* Metric strip */}
            <section className="strip">
              <div className="strip__cell">
                <span className="strip__label">Market cap</span>
                <span className="strip__value">{money(company.marketCap)}</span>
              </div>
              <div className="strip__cell">
                <span className="strip__label">Enterprise value</span>
                <span className="strip__value">{money(company.enterpriseValue)}</span>
                {!isNum(company.enterpriseValue) && (
                  <span className="strip__sub">No cash line in the filing feed</span>
                )}
              </div>
              <div className="strip__cell">
                <span className="strip__label">P/E ratio</span>
                <span className="strip__value">
                  {isNum(company.peRatio) ? num(company.peRatio, 1) : DASH}
                </span>
                {!isNum(company.peRatio) && (
                  <span className="strip__sub">Loss-making</span>
                )}
              </div>
              <div className="strip__cell">
                <span className="strip__label">Forward P/E</span>
                <span className="strip__value">
                  {isNum(company.forwardPE) ? num(company.forwardPE, 1) : DASH}
                </span>
              </div>
              <div className="strip__cell">
                <span className="strip__label">Dividend yield</span>
                <span className="strip__value">
                  {company.dividendYield > 0 ? pct(company.dividendYield, 2) : DASH}
                </span>
                {!(company.dividendYield > 0) && (
                  <span className="strip__sub">No dividend</span>
                )}
              </div>
              <div className="strip__cell strip__cell--wide">
                <span className="strip__label">52-week range</span>
                <RangeTrack
                  low={company.week52Low}
                  high={company.week52High}
                  price={company.price}
                />
              </div>
            </section>

            {/* Tabs */}
            <div className="tabs">
              <div className="tabs__list" role="tablist" aria-label="Fundamentals sections">
                {TABS.map(({ name, lock }) => (
                  <button
                    key={name}
                    type="button"
                    role="tab"
                    aria-selected={tab === name}
                    tabIndex={tab === name ? 0 : -1}
                    className={
                      "tabs__tab" +
                      (tab === name ? " tabs__tab--active" : "") +
                      (lock ? " tabs__tab--locked" : "")
                    }
                    title={lock ? lock.message : undefined}
                    /*
                     * A locked tab still SELECTS — the panel explains the lock.
                     * Making it inert would leave the padlock as the only
                     * feedback, which says "no" without saying why.
                     */
                    onClick={() => {
                      setTab(name)
                      if (lock) showToast(lock.toast)
                    }}
                  >
                    {name}
                    {lock && <LockBadge label={name} onActivate={() => { setTab(name); showToast(lock.toast) }} />}
                  </button>
                ))}
              </div>
            </div>

            {activeLock ? (
              <LockedPanel tab={tab} lock={activeLock} />
            ) : tab === "SEC filings" ? (
              <FilingsPanel filings={filings} company={company} />
            ) : tab !== "Overview" ? (
              <div className="tabs__empty" role="tabpanel">
                <p className="tabs__empty-text">{tab} data loads here.</p>
              </div>
            ) : (
              <div className="ov" role="tabpanel">
                {/* Three columns */}
                <div className="ov-grid">
                  <Panel title="Company overview">
                    <p className="ov__desc">{company.description}</p>
                    <dl className="defs">
                      <div className="defs__item">
                        <dt className="defs__label">CEO</dt>
                        <dd className="defs__value">{company.ceo}</dd>
                      </div>
                      <div className="defs__item">
                        <dt className="defs__label">Founded</dt>
                        <dd className="defs__value">{company.founded}</dd>
                      </div>
                      <div className="defs__item">
                        <dt className="defs__label">Employees</dt>
                        <dd className="defs__value">{count(company.employees)}</dd>
                      </div>
                      <div className="defs__item">
                        <dt className="defs__label">Headquarters</dt>
                        <dd className="defs__value">{company.headquarters}</dd>
                      </div>
                    </dl>
                    <a
                      className="ov__link"
                      href={"https://" + company.website}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Visit company website
                      <Icon name="arrowUpRight" size={13} />
                    </a>
                  </Panel>

                  <Panel title="Key fundamentals">
                    <div className="kvlist">
                      <Row
                        label="Revenue (TTM)"
                        value={money(company.revenueTTM)}
                        chip={<GrowthChip value={company.revenueGrowthYoY} />}
                      />
                      <Row label="Gross profit" value={money(company.grossProfit)} />
                      <Row
                        label="Net income (TTM)"
                        value={money(company.netIncomeTTM)}
                      />
                      <Row
                        label="EPS (TTM)"
                        value={usd(company.epsTTM)}
                        chip={<GrowthChip value={company.epsGrowthYoY} />}
                      />
                      <Row label="Free cash flow" value={money(company.freeCashFlow)} />
                      <Row label="Total cash" value={money(company.totalCash)} />
                      <Row label="Total debt" value={money(company.totalDebt)} />
                      <Row
                        label="Shares outstanding"
                        value={count(company.sharesOutstanding)}
                      />
                      <Row label="Float" value={count(company.float)} />
                    </div>
                  </Panel>

                  <div className="ov-stack">
                    <Panel title="Growth metrics">
                      <div className="kvlist">
                        <Row label="Revenue growth YoY" value={pct(company.revenueGrowthYoY)} />
                        <Row label="EPS growth YoY" value={pct(company.epsGrowthYoY)} />
                        <Row label="3-yr revenue CAGR" value={pct(company.revenueCagr3y)} />
                        <Row label="3-yr EPS CAGR" value={pct(company.epsCagr3y)} />
                        <Row label="5-yr revenue CAGR" value={pct(company.revenueCagr5y)} />
                        <Row label="5-yr EPS CAGR" value={pct(company.epsCagr5y)} />
                      </div>
                    </Panel>

                    <Panel title="Profitability">
                      <div className="kvlist">
                        <Row label="Gross margin" value={pct(company.grossMargin)} />
                        <Row label="Operating margin" value={pct(company.operatingMargin)} />
                        <Row label="Net margin" value={pct(company.netMargin)} />
                        <Row label="Return on equity" value={pct(company.roe)} />
                        <Row label="Return on assets" value={pct(company.roa)} />
                      </div>
                    </Panel>
                  </div>
                </div>

                {/* Annual bars */}
                <div className="barchart-grid">
                  <Panel flush>
                    <BarChart
                      title="Revenue (annual)"
                      data={revenueSeries}
                      format={v => money(v, 1)}
                    />
                  </Panel>
                  <Panel flush>
                    <BarChart
                      title="Net income (annual)"
                      data={incomeSeries}
                      format={v => money(v, 1)}
                    />
                  </Panel>
                  <Panel flush>
                    <BarChart
                      title="EPS (annual)"
                      data={epsSeries}
                      format={v => usd(v)}
                    />
                  </Panel>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
      <Toast toast={toast} onDismiss={dismissToast} />
    </Shell>
  )
}

export const Head = () => <title>Fundamentals · MarketScan</title>
